header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;else $files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=["/\\b(?:require|require_once|include|include_once)\\s*\\(?\\s*['\"]([^'\"]+)['\"]/i","/\\b(?:import|export)\\s+(?:[^'\";]+?\\s+from\\s+)?['\"]([^'\"]+)['\"]/i","/\\b(?:src|href)\\s*=\\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match('/\\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md)$/i',$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'sizes'=>$files,'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s')]);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationships</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#071016;color:#dce8ed;font-family:Inter,system-ui,sans-serif}.head{height:64px;border-bottom:1px solid #203139;padding:14px 20px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:700}.brand b{color:#55dfce}.stats{font:9px monospace;color:#70858d}.app{height:calc(100% - 64px);display:flex}.folders{width:280px;border-right:1px solid #203139;padding:16px;overflow:auto}.folders h4{margin:0 0 12px;color:#607780;font:8px monospace;letter-spacing:1px}.folder{padding:9px 10px;border-radius:7px;color:#9aaeb5;font:10px monospace;cursor:pointer;display:flex;justify-content:space-between}.folder:hover,.folder.active{background:#102128;color:#64ded2}.count{color:#526b74;font-size:8px}.main{flex:1;position:relative;overflow:auto;padding:26px}.title{color:#607780;font:8px monospace;margin-bottom:12px}.toolbar{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}.filter,.btn{border:1px solid #263d45;background:#09151b;color:#849aa2;border-radius:6px;padding:7px 9px;font:8px monospace;cursor:pointer}.filter.active,.filter:hover,.btn:hover{color:#64ded2;border-color:#55dfce66}.files{display:flex;flex-direction:column;gap:5px;max-width:950px}.file{width:100%;text-align:left;border:1px solid #263d45;background:#0a151b;border-radius:6px;padding:9px 11px;color:#91a5ac;font:9px monospace;cursor:pointer;display:flex;justify-content:space-between;align-items:center}.file:hover,.file.active{border-color:#55dfce;color:#e9ffff;background:#0d1c22}.file .right{color:#526d76;font-size:8px}.empty{color:#526a73;font:10px monospace;padding:30px 0}.note{color:#4e6872;font:8px monospace;margin:0 0 12px}.relation{position:fixed;z-index:8;right:20px;top:84px;width:340px;background:#09151bf8;border:1px solid #263d45;border-radius:8px;padding:14px;display:none;box-shadow:0 14px 45px #0008}.relation.show{display:block}.relation button{float:right;background:none;border:0;color:#71858d;font-size:18px;cursor:pointer}.relation h3{margin:7px 0 2px;font-size:13px}.path{color:#55dfce;font:8px monospace;word-break:break-all}.summary{display:flex;gap:7px;margin-top:11px}.stat{flex:1;background:#0d1c22;border-radius:6px;padding:8px}.stat b{display:block;font:12px monospace;color:#dce8ed}.stat span{font:7px monospace;color:#58717a}.list{margin-top:11px;font:8px monospace;color:#8da1a8;line-height:1.8;max-height:220px;overflow:auto}.kind{color:#9a7dff}.wire{position:fixed;inset:64px 0 0 280px;pointer-events:none}.wire line{stroke:#477d80;stroke-width:1;stroke-dasharray:5 6}.bottom{position:fixed;z-index:5;bottom:14px;left:296px;color:#566d76;font:8px monospace}.search{width:100%;margin-bottom:10px;background:#09151b;border:1px solid #263d45;border-radius:6px;padding:9px;color:#fff;outline:0;font:9px monospace}.status{position:fixed;z-index:5;right:20px;bottom:18px;color:#607982;font:8px monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#5be5bb;margin-right:6px;box-shadow:0 0 10px #5be5bb}.help{position:fixed;z-index:5;right:20px;bottom:42px;color:#405963;font:7px monospace}@media(max-width:700px){.folders{width:190px;padding:10px}.main{padding:16px}.wire{left:190px}.bottom{left:206px}.relation{left:200px;right:10px;width:auto}.head{padding:12px}.stats{display:none}.help{display:none}}
</style></head><body><header class="head"><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="stats"><?php echo count($D['files']);?> files&nbsp; • &nbsp;<?php echo count($D['refs']);?> relations&nbsp; • &nbsp;<span style="color:#55dfce">LIVE</span></div></header><div class="app"><aside class="folders"><h4>FOLDERS</h4><input id="search" class="search" placeholder="Search folders or files…"><div id="folderList"></div></aside><main class="main"><div class="title" id="crumb">SELECT A FOLDER</div><div class="toolbar"><button class="filter active" data-type="all">ALL</button><button class="filter" data-type="php">PHP</button><button class="filter" data-type="js">JS</button><button class="filter" data-type="css">CSS</button><button class="filter" data-type="other">OTHER</button></div><div class="note" id="note">Choose a folder. Files stay grouped here instead of filling the screen.</div><div id="files" class="files"><div class="empty">Select a folder to see its files.</div></div></main></div><svg id="wire" class="wire"></svg><div id="relation" class="relation"><button id="close">×</button><div class="title">FILE RELATIONSHIPS</div><h3 id="rn"></h3><div id="rp" class="path"></div><div class="summary"><div class="stat"><b id="inc">0</b><span>INCOMING</span></div><div class="stat"><b id="out">0</b><span>OUTGOING</span></div><div class="stat"><b id="total">0</b><span>TOTAL</span></div></div><div id="rl" class="list"></div></div><div class="bottom"><button class="btn" id="home">HOME</button> <button class="btn" id="refresh">RESCAN</button> <span id="hb">Server: <?php echo $D['time'];?></span></div><div class="help">folder → file → relationship • click to inspect</div><div class="status"><span class="led"></span><b id="status">LIVE</b></div>
<script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>;let current='',selected='',type='all';const $=id=>document.getElementById(id);const ext=f=>(f.split('.').pop()||'').toLowerCase();function topFolders(){return[...new Set(D.files.map(f=>f.split('/')[0]))].sort()}function directFiles(folder){return D.files.filter(f=>f.startsWith(folder+'/')&&!f.slice(folder.length+1).includes('/'))}function typeOk(f){if(type==='all')return true;const e=ext(f);if(type==='php')return e==='php';if(type==='js')return['js','mjs','jsx','ts','tsx'].includes(e);if(type==='css')return['css','scss'].includes(e);return !['php','js','mjs','jsx','ts','tsx','css','scss'].includes(e)}function human(n){if(n<1024)return n+' B';if(n<1048576)return Math.round(n/1024)+' KB';return(n/1048576).toFixed(1)+' MB'}function icon(f){const e=ext(f);return e==='php'?'PHP':(['js','mjs','jsx','ts','tsx'].includes(e)?'JS':(['css','scss'].includes(e)?'CSS':'FILE'))}function drawFolders(filter=''){const q=filter.toLowerCase();const list=$('folderList');list.innerHTML='';topFolders().filter(f=>f.toLowerCase().includes(q)||D.files.some(x=>x.startsWith(f+'/')&&x.toLowerCase().includes(q))).forEach(f=>{const b=document.createElement('div');b.className='folder'+(f===current?' active':'');b.innerHTML='<span>📁 '+f+'</span><span class="count">'+directFiles(f).length+'</span>';b.onclick=()=>openFolder(f);list.appendChild(b)})}function openFolder(f){current=f;selected='';$('crumb').textContent=f+' /';$('relation').classList.remove('show');const box=$('files');box.innerHTML='';const fs=directFiles(f).filter(typeOk).sort((a,b)=>a.localeCompare(b));$('note').textContent=fs.length+' direct files • sorted by name';if(!fs.length){box.innerHTML='<div class="empty">No files match this filter.</div>}fs.forEach(file=>{const b=document.createElement('button');b.className='file';const rel=D.refs.filter(r=>r.from===file||r.to===file).length;b.innerHTML='<span>▸ '+file.split('/').pop()+'</span><span class="right"><span class="kind">'+icon(file)+'</span> &nbsp;'+human(D.sizes[file]||0)+' &nbsp;·&nbsp; '+rel+' links</span>';b.title=file;b.onclick=()=>selectFile(file,b);box.appendChild(b)});drawFolders($('search').value)}function selectFile(file,el){selected=file;document.querySelectorAll('.file').forEach(x=>x.classList.remove('active'));el.classList.add('active');const incoming=D.refs.filter(x=>x.to===file),outgoing=D.refs.filter(x=>x.from===file),all=[...incoming.map(x=>'← '+x.from),...outgoing.map(x=>'→ '+x.to)];$('rn').textContent=file.split('/').pop();$('rp').textContent=file;$('inc').textContent=incoming.length;$('out').textContent=outgoing.length;$('total').textContent=incoming.length+outgoing.length;$('rl').innerHTML=all.length?all.slice(0,60).join('<br>'):'No direct relationships';$('relation').classList.add('show');drawWires(file)}function drawWires(file){const s=$('wire');s.innerHTML='';const refs=D.refs.filter(r=>r.from===file||r.to===file);const rect=document.querySelector('.file.active')?.getBoundingClientRect();if(!refs.length||!rect)return;refs.slice(0,20).forEach((r,i)=>{const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',rect.right);line.setAttribute('y1',rect.top+rect.height/2);line.setAttribute('x2',window.innerWidth-350);line.setAttribute('y2',105+i*20);s.appendChild(line)})}document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');type=b.dataset.type;if(current)openFolder(current)});$('search').oninput=e=>{drawFolders(e.target.value);if(current)openFolder(current)};$('close').onclick=()=>{$('relation').classList.remove('show');selected='';$('wire').innerHTML=''};$('home').onclick=()=>{current='';selected='';$('crumb').textContent='SELECT A FOLDER';$('note').textContent='Choose a folder. Files stay grouped here instead of filling the screen.';$('files').innerHTML='<div class="empty">Select a folder to see its files.</div>';drawFolders()};$('refresh').onclick=()=>location.reload();setInterval(async()=>{try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'});const d=await r.json();$('hb').textContent='Server: '+d.time;$('status').textContent='LIVE'}catch(e){$('hb').textContent='Server: offline';$('status').textContent='OFFLINE'}},2000);drawFolders();
</script></body></html>